 s=x['stages'];out.append('| '+ ' | '.join([x['consumer'],x['variant'],x['build']['package_status'],s['public_constructor'],s['input_preparation'],s['inference'] if x['consumer']=='wrapper' else s['classify_inference_and_decoding'],s['generated_getter'],x.get('earliest_failing_stage','none')])+' |')
